    [InlineData("a08x-conc", "struct Leaf\n    public var v: i32\n    public init(v: i32) => self.v = v\nstruct Leaf2\n    public var v: i32\n    public init(v: i32) => self.v = v\nfunc f<T>(x: ref/T)\n    T is (obj/Leaf) -> i32\n    T is (obj/Leaf2) -> i32\n    ()\npublic func main() -> ()\n    Console.writeLine(\"ok\")\n", "InvalidConstraint_Kd: func f<T>(x: ref/T)")]
